function frame(kind: number, id: number, op: number, payload: Uint8Array = new Uint8Array()): Uint8Array {
  const b = new Uint8Array(HEADER + payload.length);
  const d = new DataView(b.buffer);
  d.setUint32(0, payload.length, true);
  b[4] = kind;
  d.setBigUint64(5, BigInt(id), true);
  d.setUint32(13, op, true);
  b.set(payload, HEADER);
  return b;
}

/** codec.rs `AdaptError`, variant order fixed. */
export type AdaptError =
  | { kind: 'Narrow'; field: string; value: string }
  | { kind: 'NoVariant'; field: string; variant: string }
  | { kind: 'Missing'; field: string }
